import json,re
from pathlib import Path
B=Path(__file__).resolve().parents[1]
g=json.loads((B/'inputs/path_glossary_bundle.json').read_text())
bundles=g['bundles']
text='\n'.join('\n'.join(t['content'] for t in b['teaching_blocks'])+'\n'+json.dumps(b['visual_anchor'])+'\n'+json.dumps(b['practice_anchor']) for b in bundles)
terms=['Boto3','botocore.config.Config','Config','standard','total_max_attempts','max_attempts','APPROVED_ATTEMPTS','3','ClientError','Error','Code','Message','ResponseMetadata','RequestId','Cost Explorer','account','period','service','usage type','billed cost','usage','EKS','Deployment','ReplicaSets','Pods','Pod template','kubectl apply -f FILE','kubectl get deployment NAME','three replicas','infrastructure','database','application','verification','dependencies','recovery objectives','recovery capabilities','orders','Logs Insights','@timestamp','@message','REQUEST_FIELD','ID','fields','filter','sort','SNS','CloudWatch','alarm','workload','subscription','recipient','Lambda','execution role','payload','execution logs']
vocab=[t for t in terms if t in text]
sid='scenario.orders_operations'
r={'schema_version':'1.0','kind':'scenario_asset_registry','path_id':g['path_id'],'batch_id':B.name,'scenarios':[{'scenario_id':sid,'name':'Orders workload evidence review','summary':'A fictional operations team reviews supplied evidence for an orders workload: bounded automation, billed usage, fixed-replica reconciliation, restoration dependencies, request logs, alarm receipt and a bounded Lambda task. All records are authored exercise inputs, not live AWS observations. No resources, credentials or executable workspaces are provisioned.','domain':'AWS workload operations','currency':'USD','glossary_example_vocab':vocab}],'assets':[]}
def col(name,typ='string',role='text',description=None,unit=None):
 c={'name':name,'type':typ,'semantic_role':role}
 if description:c['description']=description
 if unit:c['unit']=unit
 return c
def dataset(aid,title,description,cols,rows):
 r['assets'].append({'asset_id':'ds.'+aid,'asset_kind':'dataset','scenario_id':sid,'title':title,'description':'Read-only, fictional authored exercise evidence. '+description,'columns':cols,'rows':rows,'provenance':'authored','variants':[]})
# The only concrete retry budget in the glossary is extracted, not retyped.
budget=int(re.search(r'example budget is (\d+)',bundles[0]['teaching_blocks'][3]['content']).group(1))
dataset('retry_counting','SDK request budget comparison','Config settings show initial-request versus retry counting; no AWS operation or error code is invented.',[col('configuration','string','categorical'),col('mode','string','categorical'),col('configured_value','integer','numerical'),col('initial_requests','integer','numerical'),col('maximum_retries','integer','numerical'),col('maximum_total_requests','integer','numerical')],[['total_max_attempts','standard',budget,1,budget-1,budget],['max_attempts','standard',budget,1,budget,budget+1]])
account=col('account','integer','identifier','Fictional account label, not an AWS account binding.');account['numeric_looking_label']=True
billing_cols=[account,col('period_start','date','datetime'),col('period_end','date','datetime'),col('service','string','categorical'),col('usage_type','string','categorical'),col('billed_cost','number','numerical',unit='USD'),col('usage','number','numerical'),col('usage_unit','string','categorical'),col('supplied_context')]
dataset('billing_evidence','Filtered cost and usage evidence','Selected account label 1001; selected period 2026-01-01 through 2026-01-31, inclusive. Group by service or usage_type. Costs are authored billed totals, never prices or estimates. Context is supplied exercise input; any action is only a recommendation for review.',billing_cols,[['1001','2026-01-01','2026-01-31','Compute','idle-test-usage',24,120,'exercise usage units','Supplied owner record: temporary test usage is no longer required; recommend review.'],['1001','2026-01-01','2026-01-31','Storage','required-data-usage',12,60,'exercise usage units','Supplied owner record: workload still requires this usage.'],['1002','2026-01-01','2026-01-31','Compute','idle-test-usage',48,240,'exercise usage units','Different account; exclude from selected report.'],['1001','2025-12-01','2025-12-31','Compute','idle-test-usage',36,180,'exercise usage units','Different period; exclude from selected report.']])
# Pod counts are derived from the associated identity lists in each snapshot.
pods=['orders-pod-a','orders-pod-b','orders-pod-c']
states=[('before removal',pods),('during reconciliation',pods[1:]),('after replacement',pods[1:]+['orders-pod-d'])]
dataset('deployment_reconciliation','Unchanged target and replacement Pod','Supplied NAME is orders; FILE is orders-deployment.yaml. The approved removed Pod is orders-pod-a and replacement is orders-pod-d. Snapshots support the before/during/after visual, not demand-based scaling.',[col('phase','string','categorical'),col('deployment','string','identifier'),col('requested_replicas','integer','numerical'),col('observed_replicas','integer','numerical'),col('associated_pod_identities'),col('removed_pod','string','identifier'),col('replacement_pod','string','identifier')],[[phase,'orders',budget,len(ps),', '.join(ps),None if phase=='before removal' else pods[0],'orders-pod-d' if phase=='after replacement' else None] for phase,ps in states])
steps=[('restore_infrastructure','Restore infrastructure',None,'Supplied infrastructure restoration procedure','Infrastructure can be restored in the isolated exercise.'),('verify_infrastructure','Verify infrastructure readiness','restore_infrastructure','Supplied infrastructure readiness check','Infrastructure readiness must pass before database restoration.'),('restore_database','Restore database','verify_infrastructure','Supplied database restoration procedure','Database restoration capability is supplied.'),('verify_database','Verify database readiness','restore_database','Supplied database readiness check','Database readiness must pass before application resumption.'),('resume_application','Resume orders application','verify_database','Supplied application resumption procedure','Resume only after prerequisite readiness is verified.')]
dataset('recovery_dependencies','Supplied restoration dependencies','These edges describe only the fictional workload, not a universal AWS recovery order. Qualitative objective: restore usable orders service with verified infrastructure and database prerequisites; no numerical recovery target is supplied.',[col('step_id','string','identifier'),col('step'),col('prerequisite_step_id','string','identifier'),col('supplied_capability'),col('readiness_objective')],[list(s) for s in steps])
dataset('orders_logs','Structured request evidence','Selected log group /exercise/orders; selected interval 2026-01-15T10:00:00Z through 2026-01-15T10:05:00Z. REQUEST_FIELD is request_id and selected ID is orders-request-a. Use fields @timestamp, @message, request_id | filter request_id = "orders-request-a" | sort @timestamp asc. Rows deliberately arrive out of order. Correlation is not proof that nearby errors caused the failure.',[col('log_group','string','identifier'),col('@timestamp','datetime','datetime'),col('@message'),col('request_id','string','identifier')],[['/exercise/orders','2026-01-15T10:00:03Z','Response recorded: request failed','orders-request-a'],['/exercise/orders','2026-01-15T10:00:01Z','Request received','orders-request-a'],['/exercise/orders','2026-01-15T10:00:02Z','Request failure recorded','orders-request-a'],['/exercise/orders','2026-01-15T10:00:02Z','Unrelated request failure recorded','orders-request-b'],['/exercise/orders','2026-01-15T09:59:00Z','Earlier request receipt outside selected interval','orders-request-a'],['/exercise/other','2026-01-15T10:00:01Z','Event in another group','orders-request-a']])
dataset('alarm_receipt','Notification configuration versus receipt','Approved alarm orders-alarm, approved SNS topic orders-notifications, fictional recipient orders-owner@example.invalid. Metric evaluation remains unchanged. The unconfirmed case records absent receipt evidence, not a universal delivery failure rule.',[col('case_id','string','identifier'),col('alarm','string','identifier'),col('workload','string','identifier'),col('sns_topic','string','identifier'),col('recipient','string','pii'),col('subscription_status','string','categorical'),col('metric_evaluation_changed','boolean','categorical'),col('test_notification'),col('receipt_evidence')],[['confirmed_test','orders-alarm','orders','orders-notifications','orders-owner@example.invalid','confirmed',False,'Test alarm notification: alarm=orders-alarm; workload=orders','Recipient recorded receipt with alarm and workload context.'],['unconfirmed_test','orders-alarm','orders','orders-notifications','orders-owner@example.invalid','unconfirmed',False,'Test alarm notification: alarm=orders-alarm; workload=orders',None]])
dataset('lambda_outcomes','Invocation and operational outcomes','The supplied function orders-resource-check and approved role orders-check-role are labels only. The exercise task is the glossary illustrative resource check. No new AWS action names, role policy, payload schema or executable function are invented; scoped task authority is expressed in supplied task terms.',[col('case_id','string','identifier'),col('function','string','identifier'),col('execution_role','string','identifier'),col('approved_task_scope'),col('supplied_payload'),col('invocation_status','string','categorical'),col('task_result','string','categorical'),col('execution_logs'),col('permission_context')],[['task_failed','orders-resource-check','orders-check-role','Only approved actions/resources for the supplied resource check','Supplied resource-check payload, unchanged','success','failure','Resource check completed: expected operation failed.','Do not broaden approved role.'],['task_succeeded','orders-resource-check','orders-check-role','Only approved actions/resources for the supplied resource check','Supplied resource-check payload, unchanged','success','success','Resource check completed: task succeeded.','Evidence verifies this bounded task only.'],['permission_not_approved','orders-resource-check','orders-check-role','Only approved actions/resources for the supplied resource check','Supplied resource-check payload, unchanged','success','failure','Task reports needed action absent from approved role.','Report permission/result evidence without broadening role.']])
for asset in r['assets']:
 if asset['asset_id']=='ds.billing_evidence':
  for row in asset['rows']: row[0]=int(row[0])
(B/'scenario_asset_registry.json').write_text(json.dumps(r,indent=2)+'\n')
print('scenarios',len(r['scenarios']),'assets',len(r['assets']),'rows',sum(len(a['rows']) for a in r['assets']))
